print("CURRENT:", p.observe_text_world())
print("ROOM:", p.look())

if not finished:
    actions = p.list_actions()
    water_focus = [a for a in actions if a == "focus on water"]
    if not water_focus:
        container_move = next((a for a in actions if a == "move metal pot to sink"), None)
        if container_move:
            act(container_move)
            if not finished:
                actions = p.list_actions()
                if "activate sink" in actions:
                    act("activate sink")
                    if not finished:
                        actions = p.list_actions()
                        print("SINK:", p.look())
        water_focus = [a for a in p.list_actions() if a == "focus on water"] if not finished else []
    if water_focus and not finished:
        act(water_focus[0])
        if not finished:
            actions = p.list_actions()
            if "deactivate sink" in actions:
                act("deactivate sink")
            if not finished:
                actions = p.list_actions()
                pickup = next((a for a in actions if a == "pick up metal pot"), None)
                if pickup:
                    act(pickup)
            if not finished:
                actions = p.list_actions()
                if "teleport to workshop" in actions:
                    act("teleport to workshop")
                    if not finished:
                        print("ROOM:", p.look())
    if not finished:
        actions = p.list_actions()
        print("WATER:", [a for a in actions if "water" in a and a.startswith(("focus on ", "look at ", "move ", "pick up "))][:18])
