        print("VERIFY:", p.check_success())

import primitive_api as p

print("CURRENT:", p.observe_text_world())
print("ROOM:", p.look())

if not finished:
    actions = p.list_actions()
    candidates = [a for a in actions if a.startswith("move ") and a.endswith(" to sink") and "cup containing nothing" in a]
    if candidates:
        act(candidates[0])
    if not finished:
        actions = p.list_actions()
        if "activate sink" in actions:
            act("activate sink")
    if not finished:
        print("ROOM:", p.look())
        actions = p.list_actions()
        focus = [a for a in actions if a == "focus on water"]
        if not focus:
            focus = [a for a in actions if a.startswith("focus on water in ")]
        if len(focus) == 1:
            act(focus[0])
            if not finished:
                actions = p.list_actions()
                pickups = [a for a in actions if a.startswith("pick up ") and "cup containing water" in a]
                if not pickups:
                    pickups = [a for a in actions if a.startswith("pick up ") and "cup" in a and "sink" in a]
                if len(pickups) == 1:
                    water_container = pickups[0][len("pick up "):]
                    act(pickups[0])
                else:
                    print("CUP PICKUPS:", pickups[:8])
                if not finished and pickups and len(pickups) == 1:
                    actions = p.list_actions()
                    if "deactivate sink" in actions:
                        act("deactivate sink")
                    if not finished:
                        actions = p.list_actions()
                        if "teleport to workshop" in actions:
                            act("teleport to workshop")
        else:
            print("WATER FOCUS:", focus[:6])

if not finished:
    print("ROOM:", p.look())
    print("INVENTORY:", p.inventory())
    actions = p.list_actions()
    print("WATER HANDLING:", [a for a in actions if "water" in a and a.startswith(("focus on ", "pick up ", "move ", "pour "))][:16])
    print("BATTERY CIRCUIT:", [a for a in actions if a.startswith("connect ") and "battery" in a and ("blue light bulb" in a or "water" in a)][:18])
    print("WATER CIRCUIT:", [a for a in actions if a.startswith("connect ") and "water" in a and ("blue light bulb" in a or "black wire" in a)][:18])
    print("VERIFY:", p.check_success())

import primitive_api as p

print("CURRENT:", p.observe_text_world())

if not finished:
    actions = p.list_actions()
    inspect_water = next((a for a in actions if a == "look at substance in cup"), None)
    if inspect_water:
        result = act(inspect_water)
        water_description = str(result.get("observation_after", ""))
        if not finished and "water" in water_description.lower():
            actions = p.list_actions()
            focus_water = next((a for a in actions if a == "focus on substance in cup"), None)
            if focus_water:
                act(focus_water)
                p.write_evidence("focused_sample", water_description)

if not finished:
    actions = p.list_actions()
    pickup = next((a for a in actions if a == "pick up cup containing water"), None)
    if pickup:
        act(pickup)
    if not finished:
        actions = p.list_actions()
        if "deactivate sink" in actions:
            act("deactivate sink")
    if not finished:
        actions = p.list_actions()
        if "teleport to workshop" in actions:
            act("teleport to workshop")

if not finished:
    print("ROOM:", p.look())
    print("INVENTORY:", p.inventory())
    actions = p.list_actions()
    print("SAMPLE REFERENCES:", [
        a for a in actions
        if a.startswith(("look at ", "focus on "))
        and ("water" in a or "substance" in a)
    ][:12])
    print("BATTERY TO BULB:", [
        a for a in actions if a.startswith("connect ")
        and "battery" in a and "blue light bulb" in a
    ][:16])
    print("SAMPLE CONNECTIONS:", [
        a for a in actions if a.startswith("connect ")
        and ("substance in cup" in a or " to water" in a or a.startswith("connect water to "))
        and any(t in a for t in ("battery", "blue light bulb", "black wire", "blue wire"))
    ][:24])
    print("WIRE CONNECTIONS:", [
        a for a in actions if a.startswith("connect ")
        and "black wire" in a and ("battery" in a or "blue light bulb" in a)
    ][:16])
    print("VERIFY:", p.check_success())

